def solve():
    for n in range(3, 11):
        # Same code as before
        generators = []
        for i in range(n - 1):
            generators.append(tuple(sorted((i, i + 1))))
        generators.append(tuple(sorted((0, n - 1))))

        start = tuple(range(n))
        queue = [(start, 0)]
        visited = {start: 0}

        while queue:
            curr, dist = queue.pop(0)
            for g in generators:
                i, j = g
                next_p = list(curr)
                next_p[i], next_p[j] = next_p[j], next_p[i]
                next_p = tuple(next_p)
                if next_p not in visited:
                    visited[next_p] = dist + 1
                    queue.append((next_p, dist + 1))

        max_min_dist = 0
        for p in visited:
            orbit = []
            curr_p = list(p)
            for _ in range(n):
                orbit.append(tuple(curr_p))
                last = curr_p.pop()
                curr_p.insert(0, last)

            min_d = min(visited[o] for o in orbit)
            if min_d > max_min_dist:
                max_min_dist = min_d
        print(f"N={n}, max_min_dist={max_min_dist}")

solve()

